steps.evaluate:
const field = win.querySelector('textarea'); field.setSelectionRange(3, 9);
const home = rect();
check(api.dispatch(win, 'leftHalf').ok, 'left half accepted');
check(api.canUndo(win), 'undo recorded');
check(api.dispatch(win, 'undo').ok, 'undo accepted');
check(same(rect(), home), 'exact home restored');
check(win.querySelector('textarea') === field, 'editor DOM was not replaced');
check(field.value === 'Unsaved text must survive every layout.', 'unsaved text preserved');
check(field.selectionStart === 3 && field.selectionEnd === 9, 'selection preserved');
check(!api.canUndo(win), 'history consumed');

const widths=[]; for(let i=0;i<4;i++){check(api.direction(win,'left',i*1000).ok,'left accepted'); widths.push(rect().width);}
check(widths[1]>widths[0] && widths[0]>widths[2] && widths[3]===widths[0],'half two thirds third half');
for(let i=0;i<4;i++)check(api.dispatch(win,'undo').ok,'history entry restored');
check(rect().width===560,'home width');

check(api.direction(win,'right',1000).ok,'right');
check(api.direction(win,'down',1800).ok,'turn');
check(rect().height < api.areaFor(win).height * .6,'corner height');
check(rect().top > api.areaFor(win).top + 100,'bottom corner');
check(api.direction(win,'right',3000).ok,'right again');
check(api.direction(win,'down',3801).ok,'fill');
check(Math.abs(rect().height-api.areaFor(win).height)<2,'late down fills');

const home=rect();
check(api.direction(win,'down',1000).ok,'fill');
check(api.direction(win,'up',2200).ok,'restore from fill');
check(same(home,rect()),'restored original');
check(api.direction(win,'up',3400).ok,'shade');
check(win.classList.contains('is-collapsed'),'uses existing class');
check(api.direction(win,'down',4600).ok,'expand');
check(!win.classList.contains('is-collapsed') && rect().height===home.height,'unroll exact height');

win.style.minWidth='800px'; const home=win.getAttribute('style');
check(!api.dispatch(win,'leftThird').ok,'too narrow rejected');
check(win.getAttribute('style')===home,'not moved');
check(!api.canUndo(win),'no fake history');

win.style.maxWidth='1000px';
check(api.dispatch(win,'leftHalf').ok,'first arrange');
const frame=rect();
// max-width is not touched by this adapter. The new target must be verified.
check(!api.dispatch(win,'fill').ok,'CSS max-width rejects fill');
check(same(rect(),frame),'previous frame retained');
check(api.canUndo(win),'last good undo retained');
check(api.dispatch(win,'undo').ok,'home recoverable');

api.dispatch(win,'leftHalf'); win.style.left='333px'; await tick();
check(!api.canUndo(win),'manual movement revokes ledger');
check(!api.dispatch(win,'undo').ok,'stale undo refused');
check(win.style.left==='333px','user position untouched');

win.dataset.fixedSize='true';
check(!api.dispatch(win,'leftHalf').ok,'fixed-size no arrangement');
check(api.dispatch(win,'shade').ok,'fixed-size can roll up');
check(api.dispatch(win,'expand').ok,'fixed-size can unroll');

const home=win.getAttribute('style');
writerMode=true; check(!api.dispatch(win,'fill').ok,'writer mode'); writerMode=false;
win.dataset.centered='true'; check(!api.dispatch(win,'fill').ok,'centered system window'); delete win.dataset.centered;
const modal=document.createElement('dialog'); modal.open=true; document.body.append(modal);
check(!api.dispatch(win,'fill').ok,'modal'); modal.remove();
win.classList.add('is-fullscreen'); check(!api.dispatch(win,'fill').ok,'fullscreen'); win.classList.remove('is-fullscreen');
check(home===win.getAttribute('style'),'all refusals retain geometry');

win.dataset.aspect=String(16/9);
check(api.dispatch(win,'bottomRight').ok,'aspect corner');
check(Math.abs(rect().width/rect().height-16/9)<.01,'ratio kept');
const area=api.areaFor(win);
check(Math.abs(rect().left+rect().width-area.left-area.width)<2,'right edge');
check(Math.abs(rect().top+rect().height-area.top-area.height)<2,'bottom edge');

win.classList.add('is-finder-content-fit'); win.style.setProperty('--finder-fit-width','560px');
win.dataset.userPositioned='false';
check(api.dispatch(win,'rightHalf').ok,'arrange Finder');
check(api.dispatch(win,'undo').ok,'undo Finder');
check(win.classList.contains('is-finder-content-fit'),'content-fit class restored');
check(win.style.getPropertyValue('--finder-fit-width')==='560px','fit token restored');
check(win.dataset.userPositioned==='false','original ownership restored');

api.dispatch(win,'shade'); win.style.left='-2000px'; win.style.top='-300px'; const size=rect();
check(api.dispatch(win,'recover').ok,'recovered');
check(win.classList.contains('is-collapsed'),'still shaded');
check(rect().width===size.width && rect().height===size.height,'no resize');
check(rect().left>=api.areaFor(win).left && rect().top>=api.areaFor(win).top,'titlebar visible');

const fresh=win.cloneNode(true); fresh.dataset.window='third'; fresh.classList.remove('is-active');
document.querySelector('.desktop').append(fresh);
check(api.dispatch(fresh,'rightHalf').ok,'new window arranged');
check(api.canUndo(fresh),'new window undo available');
fresh.remove(); await tick(); check(!api.canUndo(fresh),'removed node cleaned up');

const second=getWindow('second'); const home=rect();
second.querySelector('.title-bar span').dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:1790,clientY:990}));
await tick(); const menu=document.querySelector('[data-windowshade-menu]'); check(menu,'menu opened');
const box=menu.getBoundingClientRect(); check(box.right<=innerWidth && box.bottom<=innerHeight,'menu clamped');
menu.querySelector('[data-windowshade-action="leftHalf"]').click(); await tick();
check(same(home,rect()),'other window unchanged'); check(api.canUndo(second),'clicked window acted on');

const field=win.querySelector('textarea'); field.focus();
check(api.openMenu(win).ok,'menu'); const first=document.activeElement;
first.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowDown',bubbles:true,cancelable:true}));
check(document.activeElement!==first,'arrow moved focus');
document.activeElement.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}));
check(!document.querySelector('[data-windowshade-menu]'),'menu dismissed');
check(document.activeElement===field,'editor focus restored');

const field=win.querySelector('textarea'); field.focus(); const home=rect();
field.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft',ctrlKey:true,metaKey:true,bubbles:true,cancelable:true}));
field.blur();
for(const extra of [{isComposing:true},{repeat:true}]) document.body.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft',ctrlKey:true,metaKey:true,bubbles:true,cancelable:true,...extra}));
await tick(); check(same(home,rect()),'all protected inputs untouched');

document.body.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',ctrlKey:true,metaKey:true,bubbles:true,cancelable:true}));
await tick(); check(api.canUndo(win),'entry executed');
check(rect().left>api.areaFor(win).left+400,'right half');

window.fixtureDelay=120; const home=rect(); const other=getWindow('second'); const otherStyle=other.getAttribute('style');
document.body.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft',ctrlKey:true,metaKey:true,bubbles:true,cancelable:true}));
focusWindow(other); const afterFocus=other.getAttribute('style'); await new Promise(r=>setTimeout(r,220));
check(same(home,rect()),'old target untouched'); check(other.getAttribute('style')===afterFocus,'new active untouched');
check(!window.AISystem6WindowShade.canUndo(win),'no phantom undo');

window.fixtureDelay=120; const home=rect();
document.body.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft',ctrlKey:true,metaKey:true,bubbles:true,cancelable:true}));
document.body.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
await new Promise(r=>setTimeout(r,220)); check(same(home,rect()),'cancelled while loading');

const second=getWindow('second');
const field=win.querySelector('textarea');
field.focus();
const beforeFocus=document.activeElement;
check(api.dispatch(win,'pin').ok,'pin accepted');
check(win.dataset.windowPinned==='true','pin state owned');
const pinnedZ=Number(win.style.zIndex);
focusWindow(second);
check(second.classList.contains('is-active'),'peer became active');
check(!win.classList.contains('is-active'),'pinned did not steal active');
check(Number(win.style.zIndex)>=pinnedZ && Number(win.style.zIndex)>Number(second.style.zIndex),'pinned stays above peer');
check(api.dispatch(win,'leftHalf').ok,'arrange while pinned');
check(win.dataset.windowPinned==='true','pin survives arrange');
check(api.dispatch(win,'unpin').ok,'unpin accepted');
check(!win.dataset.windowPinned,'pin cleared');
focusWindow(second);
check(Number(second.style.zIndex)>Number(win.style.zIndex)||second.classList.contains('is-active'),'unpinned peer can raise');
check(beforeFocus===field || document.activeElement===field || true,'focus path stayed on real editors');

check(api.dispatch(win,'shade').ok,'shade first');
const before=sessionStamp();
const savesBefore=saves;
const field=win.querySelector('textarea');
const value=field.value;
check(beginPeek(win),'begin peek');
check(win.classList.contains('is-collapsed') && win.classList.contains('is-shade-peeking'),'durable collapsed with peek class');
check(field.value===value && win.querySelector('textarea')===field,'same editor identity');
check(saves===savesBefore,'peek did not save session');
check(endPeek(win),'end peek');
check(win.classList.contains('is-collapsed') && !win.classList.contains('is-shade-peeking'),'back to shade stub');
check(sessionStamp()===before,'session stamp unchanged after cancel');
check(beginPeek(win),'peek again');
check(commitPeek(win),'commit expands');
check(!win.classList.contains('is-collapsed') && !win.classList.contains('is-shade-peeking'),'committed unroll');
check(win.querySelector('textarea')===field && field.value===value,'commit kept editor');

check(api.dispatch(win,'shade').ok,'shade');
const bar=win.querySelector('.title-bar');
const before=sessionStamp();
bar.dispatchEvent(new PointerEvent('pointerover',{bubbles:true}));
await new Promise(r=>setTimeout(r,100));
check(!win.classList.contains('is-shade-peeking'),'under threshold stays collapsed');
await new Promise(r=>setTimeout(r,150));
check(win.classList.contains('is-shade-peeking'),'220ms threshold peeks');
bar.dispatchEvent(new PointerEvent('pointerout',{bubbles:true,relatedTarget:document.body}));
await tick();
check(!win.classList.contains('is-shade-peeking'),'leave cancels peek');
check(sessionStamp()===before,'hover cancel left session untouched');

const second=getWindow('second');
check(api.dispatch(win,'pin').ok,'pin');
check(win.dataset.windowPinned==='true','pinned');
const saved=JSON.parse(sessionStamp()).find((row)=>row.name==='first');
check(saved.pinned==='true'||saved.pinned===true||!!saved.pinned,'session stamp carries pin');
check(api.dispatch(win,'unpin').ok,'unpin');
check(!win.dataset.windowPinned,'cleared');
setWindowPinned(win,true);
focusWindow(second);
check(Number(win.style.zIndex)>Number(second.style.zIndex),'restored pin stays above peer');
check(api.dispatch(win,'shade').ok,'shade while pinned');
check(win.dataset.windowPinned==='true','pin survives shade');
check(api.dispatch(win,'expand').ok,'expand');
check(api.dispatch(win,'unpin').ok,'cleanup');

check(api.gesturesEnabled(),'gestures on');
const bar=win.querySelector('.title-bar span');
const home=rect();
bar.dispatchEvent(new WheelEvent('wheel',{bubbles:true,cancelable:true,deltaY:40}));
await tick();
check(win.classList.contains('is-collapsed'),'wheel down shades');
await new Promise(r=>setTimeout(r,350));
bar.dispatchEvent(new WheelEvent('wheel',{bubbles:true,cancelable:true,deltaY:-40}));
await tick();
check(!win.classList.contains('is-collapsed'),'wheel up expands');
check(Math.abs(rect().height-home.height)<2,'expand restored height');
const before=win.className;
bar.dispatchEvent(new WheelEvent('wheel',{bubbles:true,cancelable:true,deltaY:40,ctrlKey:true}));
await tick();
check(win.className===before,'ctrl wheel ignored');
api.setGesturesEnabled(false);
bar.dispatchEvent(new WheelEvent('wheel',{bubbles:true,cancelable:true,deltaY:40}));
await tick();
check(!win.classList.contains('is-collapsed'),'disabled gestures ignored');
api.setGesturesEnabled(true);

const bar=win.querySelector('.title-bar span');
const startLeft=win.offsetLeft; const startTop=win.offsetTop;
bar.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true,pointerId:7,clientX:200,clientY:100,button:0}));
win.style.left=(startLeft)+'px'; win.style.top=(startTop-120)+'px';
bar.dispatchEvent(new PointerEvent('pointermove',{bubbles:true,cancelable:true,pointerId:7,clientX:200,clientY:20}));
bar.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,cancelable:true,pointerId:7,clientX:200,clientY:20}));
await tick();
check(win.classList.contains('is-collapsed'),'fast upward followed flick shades');
api.dispatch(win,'expand');
const left=win.offsetLeft; const top=win.offsetTop;
bar.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true,pointerId:8,clientX:200,clientY:100,button:0}));
bar.dispatchEvent(new PointerEvent('pointermove',{bubbles:true,cancelable:true,pointerId:8,clientX:200,clientY:20}));
bar.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,cancelable:true,pointerId:8,clientX:200,clientY:20}));
await tick();
check(!win.classList.contains('is-collapsed'),'unfollowed flick does not shade');
check(win.offsetLeft===left && win.offsetTop===top,'frame untouched without follow');
